-- Source: localhost:5433/envocab
--
-- Brings a deployed database in line with local content: tags, tag
-- assignments, notebook naming and hand-edited word meanings.
--
-- Safe to run repeatedly. Keyed on natural keys (word, slug), never on
-- numeric ids, so it does not care that ids differ between machines.
-- Touches no users, no review progress and no question attempts.
--
--   psql "$DATABASE_URL" -f server/sql/sync-content.sql

-- This file is UTF-8. On Windows psql defaults client_encoding to the
-- console codepage (WIN1252), which makes it read the Vietnamese meanings
-- and IPA symbols as mojibake and abort with
--   ERROR: character with byte sequence 0x8f in encoding "WIN1252"
-- Setting it here means the file works whatever codepage the caller uses.
SET client_encoding = 'UTF8';

