  ('amphibian', 'động vật lưỡng cư', 'a cold-blooded vertebrate such as a frog', 'động vật lưỡng cư', NULL, '/æmˈɪbɪən/', NULL),
  ('amplify', 'khuếch đại, làm tăng', 'to increase the volume or significance', 'khuếch đại, làm tăng', 'magnify, increase, intensify', '/ˈæmplɪfaɪ/', NULL),
  ('an old flame', NULL, 'someone who you had a romantic relationship with in the past', 'một mối tình cũ', '', '', 'Last week Alec was seen dining with his old flame Janine Turner in New York.'),
  ('an own goal', NULL, '[BRITISH] a course of action which is intended to bring an advantage and which instead causes a problem', '[bóng đá] bàn thắng phản lưới nhà', '', '', 'It was a classic own goal by the fashion house. They brought their prices down to attract more customers but lost the high-end customers that they already had.'),
  ('analogical', 'tương tự, loại suy', 'based on or relating to analogy', 'tương tự, loại suy', 'analogous, comparable, parallel', '/ˌænəˈlɑːdʒɪk əl/', NULL),
  ('analogous', 'adjective: similar in some respects but otherwise different', 'adjective: similar in some respects but otherwise different', 'tương tự', NULL, NULL, 'There are few animals that form partnerships analogous to marriage, but among them are eagles, wolves, and even some fish.'),
  ('analogy', 'noun: a comparison of two very different things that have one similar aspect', 'noun: a comparison of two very different things that have one similar aspect', 'phép so sánh', NULL, NULL, 'There are surprising analogies we can make between medicine and warfare, especially in cancer treatment, which uses radiation to attack tumors.'),
  ('analytical', NULL, 'using a logical method of thinking about something in order to understand it, especially by looking at all the parts separately', 'dùng phép phân tích', '', '/ˌænəˈlɪtɪkl/ ', 'She has a clear analytical mind. an analytic approach to the problem'),
  ('analyze', 'verb: to try to understand something better by closely looking at its details', 'verb: to try to understand something better by closely looking at its details', 'phân tích', 'scrutinize, dissect, evaluate', '/əˈnæl.ɪz/', 'The accountant was too busy with paperwork to analyze the report that said the company had no money.'),
  ('ancestor', 'tổ tiên, tiền bối', 'a person from whom one is descended; a forerunner', 'tổ tiên, tiền bối', 'forebear, forefather, progenitor', '/ˈæn.sestər/', NULL),
  ('ancestral', 'thuộc tổ tiên, gia truyền', 'belonging to or inherited from ancestors', 'thuộc tổ tiên, gia truyền', 'hereditary, inherited, forebear', '/ænˈsestrəl/', NULL),
  ('and', 'used to connect words or ideas of the same kind', 'used to connect words or ideas of the same kind', 'và', 'plus, as well as', '/ænd/', 'The scheme is cheap and easy to administer.'),
  ('animation', NULL, 'energy and enthusiasm in the way you look, behave or speak Tính hoạt bát, sinh khí.', 'Lòng hăng hái, nhiệt tình; sự cao hứng, sự hào hứng.', '', '/ˌænɪˈmeɪʃn/', 'His face was drained of all colour and animation. She talked about her new job with great animation. She spoke with great animation about her latest discoveries.'),
  ('annotate', 'chú thích', 'to add notes giving explanation', 'chú thích', 'comment, explain, gloss', '/ˈænəteɪt/', NULL),
  ('annual', 'adjective: yearly; happening every year', 'adjective: yearly; happening every year', 'hàng năm', NULL, NULL, 'Everyone in Manchester was excited about the annual game between the city''s two soccer teams.'),
  ('anomalous', 'adjective: not normal', 'adjective: not normal', 'bất thường, dị thường', 'abnormal, atypical, irregular', '/əˈnɑːmələs/', 'According to those who don''t believe in climate change, the extreme weather over the last five years is simply anomalous and won''t continue for long.'),
  ('anomaly', 'noun: something that is not normal, standard, or expected', 'noun: something that is not normal, standard, or expected', 'sự bất thường', 'irregularity, abnormality, aberration', '/əˈnɑːməli/', 'After finding anomalies in the data from her experiment on the effects of caffeine on turtles, Anne decided to start again.'),
  ('antenna', 'râu (côn trùng); ăng-ten', 'a sensory appendage; a device for signals', 'râu (côn trùng); ăng-ten', 'feeler, aerial', '/ænˈtenə/', NULL),
