  ('anthropogenic', 'do con người gây ra', 'caused or influenced by human activity', 'do con người gây ra', 'human-caused, man-made', '/ænθrəpəˈdʒɪnik/', NULL),
  ('anti-social', NULL, 'harmful to society often avoiding spending time with other people hay xa lánh người khác', 'có hại cho xã hội', '', '/ˌæntiˈsoʊʃl/', 'Increasingly, smoking is regarded as an antisocial habit. They''ll think you''re being antisocial if you don''t go'),
  ('anticipate', 'dự đoán, lường trước', 'to expect or predict', 'dự đoán, lường trước', 'expect, predict, foresee', '/ænˈtɪsɪpeɪt/', NULL),
  ('antipathy', 'ác cảm', 'a deep-seated feeling of dislike', 'ác cảm', 'hostility, aversion, dislike', '/ænˈtɪpəθi/', NULL),
  ('antithetical', 'trái ngược hoàn toàn', 'directly opposed; mutually incompatible', 'trái ngược hoàn toàn', 'opposite, contrary, contradictory', '/ˌæntɪˈθetɪkəl/', NULL),
  ('apathetic', 'adjective: with no emotion or interest', 'adjective: with no emotion or interest', 'thờ ơ', NULL, NULL, 'Mr. Thompson was so talented at teaching math that even normally apathetic students took interest.'),
  ('apathy', 'noun: an absence of emotion or enthusiasm', 'noun: an absence of emotion or enthusiasm', 'sự thờ ơ, vô cảm', '', '', 'The hardest part of teaching high-school math is fighting apathy in my students—or for that matter, keeping them awake at all.'),
  ('apex', 'noun: the highest point', 'noun: the highest point', 'đỉnh', NULL, NULL, 'Top athletes in most sports hit the apexes of their careers in their 20s or early 30s, after which health becomes harder to maintain.'),
