  ('artistic', 'có tính nghệ thuật', 'having or revealing natural creative skill', 'có tính nghệ thuật', 'creative, aesthetic, expressive', '/ɑːrˈtɪstɪk/', NULL),
  ('artwork', 'tác phẩm nghệ thuật', 'an artistic creation, especially a painting or drawing', 'tác phẩm nghệ thuật', 'artifact, creation, masterpiece', '/ɑːrt.woʊk/', NULL),
