  ('assume', 'verb: to believe without proof', 'verb: to believe without proof', 'giả định', NULL, NULL, 'Ahmed assumed his forgetful professor wouldn''t remember their meeting, but the professor was already waiting for him in her office.'),
  ('assumption', 'giả định, sự cho là', 'a thing accepted as true without proof', 'giả định, sự cho là', 'presumption, supposition, premise', '/əˈsʌmpʃən/', NULL),
  ('assure', NULL, 'to tell somebody that something is definitely true or is definitely going to happen, especially when they have doubts about it', 'làm cho vững tâm, làm cho tin chắc, quả quyết, cam đoan', '', ' /əˈʃʊr/', 'You think I did it deliberately, but I assure you (that) I did not. We were assured that everything possible was being done.'),
  ('asteroid', 'tiểu hành tinh', 'a small rocky body orbiting the sun', 'tiểu hành tinh', 'planetoid', '/æsˈtɛrɔɪd/', NULL),
  ('astronomer', 'nhà thiên văn học', 'a scientist who studies celestial objects', 'nhà thiên văn học', 'stargazer', '/əˈstrənəmər/', NULL),
  ('astronomical', NULL, 'connected with astronomy (of an amount, a price, etc.) very large Vô cùng to lớn.', ' (thuộc) Thiên văn, (thuộc) thiên văn học.', '', '/ˌæstrəˈnɑːmɪkl/ ', 'astronomical observations the astronomical price of land for building The figures are astronomical.'),
  ('astute', 'adjective: able to see the most important information to make a decision', 'adjective: able to see the most important information to make a decision', 'thông minh', NULL, NULL, 'Alfonzo was an astute chess player, always ready to use an opponent''s misplay as an opportunity to attack.'),
  ('at cross purposes', NULL, 'two people think they are talking about or trying to do the same thing as each other, but they are actually talking about or trying to do different things', 'ông nói gà bà nói vịt', '', '', 'They had been talking at cross purposes earlier, he realized. They hadn’t been offering him a share of the deal at all.'),
  ('at each other’s (one another’s) throats', NULL, 'arguing in a very angry way', 'cãi nhau kịch liệt', '', '', 'The politicians are at one another’s throats all the time, and are not functioning as a very effective government.'),
  ('atmospheric', 'thuộc khí quyển; gợi không khí', 'relating to the atmosphere; evocative of a mood', 'thuộc khí quyển; gợi không khí', 'evocative, aerial', '/ætmoʊsˈferɪk/', NULL),
  ('atom', 'nguyên tử', 'the smallest unit of a chemical element', 'nguyên tử', NULL, '/ætəm/', NULL),
  ('attenuate', 'làm giảm, làm yếu đi', 'to reduce the force or value', 'làm giảm, làm yếu đi', 'weaken, lessen, diminish', '/əˈtenjueɪt/', NULL),
  ('attitude', 'noun: a set way of thinking or a set feeling about something or someone', 'noun: a set way of thinking or a set feeling about something or someone', 'thái độ', NULL, NULL, 'Zach always has a positive attitude when he has to deal with a problem at work.'),
  ('attract', 'thu hút, hấp dẫn', 'to draw in or cause to come closer', 'thu hút, hấp dẫn', 'allure, entice, captivate', '/əˈtrækt/', 'I had always been attracted by the idea of working abroad. These flowers are brightly coloured in order to attract butterflies. I am attracted to Mary. She''s just so beautiful!'),
