  ('disregard', 'phớt lờ, không quan tâm', 'to pay no attention to; to ignore', 'phớt lờ, không quan tâm', 'ignore, overlook, neglect', '/ˌdɪsrɪˈɡɑːrd/', NULL),
  ('disrupt', 'làm gián đoạn, phá vỡ', 'to interrupt or disturb the normal course of', 'làm gián đoạn, phá vỡ', 'interrupt, upset, derail', '/dɪsˈræpt/', NULL),
