  ('dissipate', 'verb: to completely separate in all directions', 'verb: to completely separate in all directions', 'tan biến', NULL, NULL, 'Three days after I accidentally cooked a mouse that had crawled into my oven, the smell still hasn''t dissipated.'),
  ('dissociate', 'tách rời, không liên quan', 'to disconnect or separate from something', 'tách rời, không liên quan', 'separate, disconnect, distance', '/dɪˈsoʊsieɪt/', NULL),
  ('dissolve', 'hỏa tan, tan rã', 'to make or become incorporated into a liquid', 'hỏa tan, tan rã', 'liquefy, disintegrate, melt', '/dɪˈzɒlv/', 'Salt dissolves in water. Heat gently until the sugar dissolves.'),
