  ('distinct', 'adjective: clearly different from another thing', 'adjective: clearly different from another thing', 'rõ ràng, khác biệt', 'separate, different, unmistakable', '/dɪˈstɪŋkt/', 'There are at least five distinct types of turtle living on the island.'),
  ('distinction', 'sự khác biệt, sự xuất sắc', 'a difference or contrast; excellence or eminence', 'sự khác biệt, sự xuất sắc', 'differentiation, disparity, distinctiveness', '/dɪˈstɪŋkʃən/', NULL),
  ('distinctive', 'đặc biệt, riêng biệt', 'having a quality that marks something as different', 'đặc biệt, riêng biệt', 'characteristic, unique, idiosyncratic', '/dɪˈstɪŋktɪv/', NULL),
