  ('dormant', 'adjective: inactive now but able to become active later', 'adjective: inactive now but able to become active later', 'không hoạt động', NULL, NULL, 'A wasp in winter may seem to be frozen when in fact she is merely hibernating; she is not dead, but dormant.'),
  ('dose', NULL, 'an amount of a medicine or a drug that is taken once, or regularly over a period of time', 'liều lượng, liều thuốc', '', ' /doʊs/', 'a high/low dose a dose of penicillin Take a single dose at bedtime to help you sleep. I always take my daily dose of vitamin C.'),
  ('down the drain (plughole, toilet)', NULL, 'be lost or wasted', 'chảy xuống cống (lỗ thoát nước, bồn cầu)', '', '', 'You have ruined everything – my perfect plans, my great organization. All those years of work are down the drain.'),
  ('downfall', 'noun: a sudden loss of power or success', 'noun: a sudden loss of power or success', 'sự sụp đổ', NULL, NULL, 'An inability to match the lower prices of its competitors led to the company''s downfall.'),
