  ('earnings', 'thu nhập, tiền kiếm được', 'money obtained from work or investment', 'thu nhập, tiền kiếm được', 'income, proceeds, revenue', '/ˈɜːrnɪŋz/', 'a rise in average earnings compensation for loss of earnings caused by the accident'),
  ('eccentric', 'adjective: clearly unusual (used for people or behavior)', 'adjective: clearly unusual (used for people or behavior)', 'lập dị', 'unconventional, odd, quirky', '/ɪkˈsentrɪk/', 'Most people considered him a harmless eccentric. Aunt Matilda was something of an eccentric.'),
  ('eccentricity', 'tính lập dị', 'unconventional behavior', 'tính lập dị', 'peculiarity, oddity, idiosyncrasy', '/ˌeksenˈtrɪsəti/', NULL),
  ('echo', 'tiếng vang; vọng lại', 'a sound reflected back; to repeat or imitate', 'tiếng vang; vọng lại', 'reverberation, resonance, reflection', '/ˈɛkoʊ/', 'The echoes of his scream sounded in the cave for several seconds. Thick carpet would reduce the echo in this hallway.'),
  ('echolocation', 'định vị bằng tiếng vang', 'locating objects by reflected sound', 'định vị bằng tiếng vang', NULL, '/ɪkəʊˈloʊʃən/', NULL),
