  ('erratic', 'adjective: often changing suddenly and unpredictably', 'adjective: often changing suddenly and unpredictably', 'thất thường', 'irregular, inconsistent, unpredictable', '/ɪˈrætɪk/', 'The wild, sudden turns of the car led the police officer to investigate; when asked about his erratic driving, the driver had no explanation.'),
  ('eschew', 'tránh né', 'to deliberately avoid using', 'tránh né', 'avoid, shun, abstain from', '/esˈtʃuː/', NULL),
  ('esoteric', 'huyền bí, kén người hiểu', 'intended for or understood by only a small group', 'huyền bí, kén người hiểu', 'arcane, abstruse, obscure', '/ˌesəˈterɪk/', NULL),
  ('especially', 'to a great extent; above all', 'to a great extent; above all', 'đặc biệt là', 'particularly, above all', '/ɪˈspeʃ.əl.i/', 'Air quality matters, especially for children.'),
  ('essay', 'bài luận, tiểu luận', 'a short piece of writing on a particular subject', 'bài luận, tiểu luận', 'composition, treatise, discourse', '/ˈeɪ.si/', NULL),
