INSERT INTO vocabulary (word, meaning, english_meaning, vietnamese_meaning, synonyms, phonetic, example) VALUES
  ('establish', 'verb: to build, to create (a system, organization, or idea)', 'verb: to build, to create (a system, organization, or idea)', 'thành lập', NULL, NULL, 'The U.S. government was established in the late 1700s.'),
  ('establishment', NULL, 'the act of starting or creating something that is meant to last for a long time', 'sự thành lập, sự thiết lập, sự kiến lập', '', ' /ɪˈstæblɪʃmənt/', 'The speaker announced the establishment of a new college. the establishment of diplomatic relations between the countries'),
  ('esteem', 'noun: respect from people', 'noun: respect from people', 'sự kính trọng', NULL, NULL, 'The students held their professor in high esteem: she was not only a well-known author, but also a wise teacher and a friendly mentor.'),
  ('estimate', 'verb: to roughly determine the value or number of something; to guess a number using some information', 'verb: to roughly determine the value or number of something; to guess a number using some information', 'ước tính', 'calculate, gauge, judge', '/ˈestɪmeɪt/', 'Be careful to not forget any costs for the year when you estimate your budget.'),
  ('evade', 'verb: to not be caught; to avoid', 'verb: to not be caught; to avoid', 'tránh né', NULL, NULL, 'The burglars evaded the police by driving as quickly as they could through a narrow and twisting road.'),
  ('evaluate', 'verb: to form an idea of the amount, number, or value of something', 'verb: to form an idea of the amount, number, or value of something', 'dánh giá', 'appraise, assess, gauge', '/ɪˈvæljuˌeɪt/', 'Students are evaluated by their grades on tests, homework, essays, and in-class interaction.'),
  ('evaporation', NULL, 'the process of a liquid changing or being changed into a gas', 'sự làm bay hơi, sự bay hơi', '', ' /ɪˌvæpəˈreɪʃn/', 'Heat and wind can cause evaporation. Snow cover prevents evaporation of water from the soil.'),
  ('evasion', 'sự né tránh', 'the action of avoiding something', 'sự né tránh', 'avoidance, escape, dodging', '/ɪˈveɪʒən/', NULL),
  ('even though', 'despite the fact that, used for emphasis', 'despite the fact that, used for emphasis', 'mặc dù, ngay cả khi', 'although, notwithstanding', NULL, 'Even though costs rose, demand held steady.'),
  ('every cloud has a silver lining', NULL, 'every sad or difficult situation has a positive side', 'bất cứ vấn đề xấu gì cũng đều có một mặt tốt trong đó', '', '', 'I''m sorry your business is going badly, but don''t despair. Every cloud has a silver lining. When Mary''s friends visited her in the hospital, they tried to cheer her up, but Mary never could find the silver lining in the cloud of her illness.'),
  ('evident', 'adjective: clearly seen or understood; obvious', 'adjective: clearly seen or understood; obvious', 'hiển nhiên, rõ ràng', 'apparent, manifest, conspicuous', '/ɪˈvɛdənt/', 'Dogs'' feelings are usually evident in their actions.'),
  ('evince', 'biểu lộ, cho thấy', 'to show or reveal a quality clearly', 'biểu lộ, cho thấy', 'show, display, manifest', '/ɪˈvɪns/', NULL),
  ('evolution', NULL, '(biology) the gradual development of plants, animals, etc. over many years as they adapt to changes in their environment', 'sự tiến hoá, sự phát triển', '', '/ˌevəˈluːʃn/', 'the evolution of the human species Darwin’s theory of evolution'),
  ('evolutionary', 'thuộc tiến hóa', 'relating to gradual development, especially of species', 'thuộc tiến hóa', 'developmental, progressive', '/ˌɛvəˈluːʃənəri/', NULL),
  ('evolve', 'tiến hóa, phát triển', 'to develop gradually over time', 'tiến hóa, phát triển', 'develop, progress, metamorphose', '/ɪˈvɒlv/', NULL),
  ('exacerbate', 'verb: to make worse', 'verb: to make worse', 'làm trầm trọng thêm', 'aggravate', '/ɪɡˈzæsərbeɪt/', 'His aggressive reaction only exacerbated the situation. The symptoms may be exacerbated by certain drugs. This attack will exacerbate the already tense relations between the two communities.'),
  ('exacting', 'adjective: requiring and demanding accuracy', 'adjective: requiring and demanding accuracy', 'khắt khe', NULL, NULL, 'Though his childhood piano teacher was so exacting, Max is thankful now, having become a professional pianist.'),
