  ('examine', 'xem xét, khảo sát', 'to inspect or scrutinize something in detail', 'xem xét, khảo sát', 'scrutinize, inspect, investigate', '/ɪɡˈzæmɪn/', NULL),
  ('excavate', 'verb: to remove by digging in the ground', 'verb: to remove by digging in the ground', ' khai quật', '', '/ˈekskəveɪt/', ''),
  ('exceed', 'vượt quá, vượt trội', 'to be greater than; to surpass a limit', 'vượt quá, vượt trội', 'surpass, transcend, outstrip', '/ɪkˈsɪd/', NULL),
  ('excessive', 'quá mức', 'more than necessary; immoderate', 'quá mức', 'immoderate, extravagant, undue', '/ɪkˈsesɪv/', NULL),
  ('exchange', 'sự trao đổi', 'an act of giving in return for receiving', 'sự trao đổi', 'trade, swap, interchange', '/ɪksˈtʃeɪndʒ/', NULL),
  ('excite', 'kích thích, làm phấn khích', 'to arouse strong feeling or activity', 'kích thích, làm phấn khích', 'stimulate, provoke, invigorate', '/ɪkˈsaɪt/', NULL),
  ('exclude', 'verb: to not include; to keep out of a list or group', 'verb: to not include; to keep out of a list or group', 'loại trừ, loại bỏ', 'omit, preclude, debar', '/ɪkˈskluːd/', 'Tom has been excluded from school (= he is not allowed to go to school) for bad behaviour. Try excluding fat from your diet. Buses run every hour, Sundays excluded.'),
  ('exclusively', 'chỉ, độc quyền', 'to the exclusion of all others; only', 'chỉ, độc quyền', 'solely, uniquely, entirely', '/ɪkˈskluːsɪvlɪ/', NULL),
  ('executive authority', 'quyền hành pháp', NULL, 'quyền hành pháp', NULL, '/ɪɡˈzekjətɪv ɔːˈθɒrəti/', NULL),
  ('exemplar', 'tấm gương, mẫu mực', 'a person serving as a typical example', 'tấm gương, mẫu mực', 'model, paragon, example', '/ɪɡˈzemplɑːr/', NULL),
  ('exemplify', 'làm ví dụ điển hình', 'to be a typical example of; to illustrate by example', 'làm ví dụ điển hình', 'epitomize, typify, illustrate', '/ɪɡˈzɛmplaɪ/', NULL),
  ('exert', 'gắng sức, thi thố', 'to apply or bring to bear, as force or influence', 'nỗ lực', 'exercise, wield, apply', '/ɪɡˈzɜːrt/', ''),
  ('exhaust', 'dùng hết, làm kiệt sức', 'to use up resources; to tire out', 'dùng hết, làm kiệt sức', 'deplete, drain, consume', '/ɪɡˈzɔːst/', 'Within three days they had exhausted their supply of food. How long will it be before the world''s fuel supplies are exhausted?'),
  ('exhaustive', 'adjective: complete and very detailed', 'adjective: complete and very detailed', 'đầy đủ, toàn diện', 'thorough, comprehensive, complete', '/ɪɡˈzɔːstɪv/', 'Wikipedia makes no claim to be an exhaustive encyclopedia, as many more obscure topics don''t even have pages.'),
  ('exhibit', 'trưng bày; biểu lộ', 'to display or show something publicly; evidence', 'trưng bày; biểu lộ', 'display, manifest, showcase', '/ɪɡˈzɪbɪt/', NULL),
  ('exhibition', 'cuộc triển lãm', 'a public display of art or items', 'cuộc triển lãm', 'display, show, presentation', '/ˌeksɪˈbɪʃən/', NULL),
  ('exiguous', 'rất nhỏ, ít ỏi', 'very small in size or amount', 'rất nhỏ, ít ỏi', 'meager, scant, sparse', '/ɪɡˈzɪɡjuəs/', NULL),
  ('exorbitant', 'quá đáng, cắt cổ', 'exceeding what is reasonable', 'quá đáng, cắt cổ', 'excessive, extravagant, immoderate', '/ɪɡˈzɔːrbɪtənt/', NULL),
  ('expand', 'verb: to make larger; to give more detail on a subject', 'verb: to make larger; to give more detail on a subject', 'mở rộng', 'enlarge, extend, develop', '/ɪkˈspænd/', 'Blowing air into a balloon will cause it to expand, but if you blow too much air, it will explode!'),
  ('expanse', 'khoảng rộng lớn, dài', 'a wide continuous area of something', 'khoảng rộng lớn, dài', 'stretch, sweep, extent', '/ɪkˈspæns/', NULL),
  ('expansive', 'rộng lớn, bao la', 'covering a wide area; open and communicative', 'rộng lớn, bao la', 'extensive, sweeping, comprehensive', '/ɪkˈspænsɪv/', NULL),
  ('expectancy', 'sự mong đợi; tuổi thọ dự kiến', 'the state of expecting; anticipated duration', 'sự mong đợi; tuổi thọ dự kiến', 'anticipation, expectation', '/ɪkˈspektənsi/', NULL),
  ('expectation', 'kỳ vọng, sự mong đợi', 'a strong belief that something will happen', 'kỳ vọng, sự mong đợi', 'anticipation, assumption, prospect', '/ɪkˈspekʃən/', NULL),
  ('expedite', 'đẩy nhanh, xúc tiến', 'to make happen sooner; to speed up', 'đẩy nhanh, xúc tiến', 'accelerate, hasten, speed up', '/ˈekspədaɪt/', NULL),
  ('expense', 'chi phí, phí tổn', 'the cost required for something', 'chi phí, phí tổn', 'cost, expenditure, outlay', '/ɪkˈspɛns/', 'The garden was transformed at great expense. No expense was spared (= they spent as much money as was needed) to make the party a success.'),
  ('experimental', 'mang tính thực nghiệm', 'based on untested ideas or techniques; exploratory', 'mang tính thực nghiệm', 'exploratory, empirical, trial', '/ɪkˈspɜːrɪməntl/', NULL),
  ('explicable', 'có thể giải thích', 'able to be accounted for', 'có thể giải thích', 'explainable, understandable, accountable', '/ɪkˈsplɪkəbəl/', NULL),
  ('exploit', 'khai thác; lợi dụng', 'to make full use of; to take unfair advantage', 'khai thác; lợi dụng', 'utilize, leverage, capitalize on', '/ɪkˈsplɔɪt/', NULL),
  ('exploration', 'sự khám phá, thăm dò', 'the action of examining or investigating', 'sự khám phá, thăm dò', 'investigation, expedition, inquiry', '/ɪksploʊrˈeɪʃən/', NULL),
  ('export', 'xuất khẩu', 'to send goods to another country for sale', 'xuất khẩu', 'ship, dispatch', '/ɪkˈspɔːrt/', NULL),
  ('expose', 'verb: to show or reveal something that was hidden', 'verb: to show or reveal something that was hidden', 'phơi bày, tiết lộ', 'reveal, uncover, disclose', '/ɪkˈspoʊz/', 'The politician''s crimes were exposed and he was forced to leave his position.'),
  ('exposure', NULL, 'the fact of experiencing something or being affected by it because of being in a particular situation or place', 'sự tiếp xúc trực tiếp với cái gì đấy', '', ' /ɪkˈspoʊʒər/', 'According to received wisdom, exposure to low level radioactivity is harmless. She gradually became deaf after lengthy exposure to noise in the workplace.'),
  ('expound', 'trình bày chi tiết', 'to present and explain in detail', 'trình bày chi tiết', 'explain, elucidate, expand', '/ɪkˈspaʊnd/', NULL),
  ('extant', 'còn tồn tại, hiện hữu', 'still in existence; surviving', 'còn tồn tại, hiện hữu', 'surviving, existing, remaining', '/ɪkˈstænt/', NULL),
  ('extemporaneous', 'ứng khẩu, tức hứng', 'spoken without preparation', 'ứng khẩu, tức hứng', 'impromptu, spontaneous, off-the-cuff', '/ɪkˌstempəˈreɪniəs/', NULL),
  ('external', 'adjective: outside (especially of a body or system)', 'adjective: outside (especially of a body or system)', 'bên ngoài', NULL, NULL, 'Uncontrollable, external events can cause even a very careful company to fail.'),
  ('external validation', 'sự công nhận từ bên ngoài', NULL, 'sự công nhận từ bên ngoài', NULL, '/ɪkˈstɜːnl ˌvælɪˈdeɪʃn/', NULL),
  ('extinct', 'adjective: not existing anymore', 'adjective: not existing anymore', 'tuyệt chủng, tuyệt diệt', 'defunct, vanished, obsolete', '/ɪkˈstriŋkt/', 'The dodo bird has been extinct for more than 350 years—the last confirmed sighting was in 1662.'),
  ('extinction', 'sự tuyệt chủng', 'the state of a species having died out completely', 'sự tuyệt chủng', 'annihilation, eradication, extermination', '/ɪkˈstɪŋkʃən/', NULL),
  ('extirpate', 'diệt trừ tận gốc', 'to root out and destroy completely', 'diệt trừ tận gốc', 'eradicate, eliminate, exterminate', '/ˈekstərpeɪt/', NULL),
  ('extol', 'ca tụng, tán dương', 'to praise enthusiastically', 'ca tụng, tán dương', 'praise, laud, exalt', '/ɪkˈstoʊl/', NULL),
  ('extort', 'tống tiền, cưỡng đoạt', 'to obtain by force or threats', 'tống tiền, cưỡng đoạt', 'coerce, blackmail, force', '/ɪkˈstɔːrt/', NULL),
  ('extract', 'verb: to take out by force', 'verb: to take out by force', 'trích đoạn', NULL, NULL, 'Some cheeses aren''t vegetarian because they''re made using a liquid called "rennet," which is extracted from cow''s stomachs.'),
  ('extraction', 'sự chiết xuất, khai thác', 'the process of removing or obtaining something', 'sự chiết xuất, khai thác', 'removal, withdrawal, derivation', '/ɪkˈstrækʃən/', NULL),
  ('extraneous', 'không liên quan, lạc đề', 'irrelevant or unrelated', 'không liên quan, lạc đề', 'irrelevant, unrelated, immaterial', '/ɪkˈstreɪniəs/', NULL),
  ('extrapolate', 'ngoại suy', 'to extend application by inference', 'ngoại suy', 'infer, deduce, project', '/ɪkˈstræpəleɪt/', NULL),
  ('extravagant', 'adjective: more than is needed; overly expensive', 'adjective: more than is needed; overly expensive', 'hoành tráng', NULL, NULL, 'Susie''s wedding was extravagant, with a dinner of steak and lobster, invitations decorated with gold, and a ceremony at a castle.'),
  ('extricate', 'gỡ ra, thoát ra', 'to free from a difficulty', 'gỡ ra, thoát ra', 'free, release, disentangle', '/ˈekstrɪkeɪt/', NULL),
  ('fable', 'noun: a traditional story that teaches a lesson', 'noun: a traditional story that teaches a lesson', 'truyện ngụ ngôn', NULL, NULL, 'Grandma''s fables always had very specific lessons; my favorites were "The elf that always left the toilet seat up" and "the fairy that chatted on Facebook instead of getting Granny a glass of water."'),
  ('fabric', NULL, 'cloth or material for making clothes, covering furniture, etc.', 'vải vóc', '', '/ˈfæbrɪk/', 'cotton fabric furnishing fabrics'),
  ('facet', 'noun: one side or aspect (used for abstract things)', 'noun: one side or aspect (used for abstract things)', 'mặt, khía cạnh
', '', '', 'After two years of living abroad, Mario decided that he missed some facets of American food culture, including the variety of restaurant types.'),
  ('facilitate', 'tạo điều kiện, hỗ trợ', 'to make an action or process easier', 'tạo điều kiện, hỗ trợ', 'enable, expedite, ease', '/fəˈsɪleɪteɪt/', 'Classical music, unlike many types of music, will generally facilitate learning and improve memory.'),
  ('factor', 'noun: a fact that influences or changes a result', 'noun: a fact that influences or changes a result', 'yếu tố', NULL, NULL, 'Two of the largest factors affecting children''s healthy growth are food and relationships with parents.'),
  ('faint', 'adjective: very light or small (of a feeling or sense)', 'adjective: very light or small (of a feeling or sense)', 'nhạt nhòa', NULL, NULL, 'A gust of cool autumn wind blew through the window, and Sebastian felt a faint chill on the back of his neck.'),
  ('fair and square', NULL, 'do something without cheating or lying', 'một cách công bằng và minh bạch', '', '', 'My father bought them fair and square fifty years ago. We’ve still got the receipts.'),
  ('fall flat on your face', NULL, 'fail or make an embarrassing mistake', 'ngã sấp mặt', '', '', 'He was trying to introduce changes in the prison system but he fell flat on his face.'),
  ('familiarity', 'sự quen thuộc, thông thạo', 'close acquaintance or knowledge of something', 'sự quen thuộc, thông thạo', 'acquaintance, conversance, intimacy', '/fəˈmɪlɪərəti/', NULL),
  ('fantastical', 'kỳ ảo, hoang đường', 'imaginative or fanciful; remote from reality', 'kỳ ảo, hoang đường', 'fanciful, surreal, whimsical', '/fænˈtæstɪkəl/', NULL),
  ('far from', 'not at all; the opposite of', 'not at all; the opposite of', 'còn lâu mới, hoàn toàn không', 'by no means, anything but', NULL, 'The results are far from conclusive.'),
  ('farmer', 'nông dân', 'a person who cultivates land or raises livestock', 'nông dân', 'grower, agriculturalist', '/ˈfɑːrmər/', NULL),
  ('fascinating', NULL, 'extremely interesting and attractive', 'làm mê, làm say mê, quyến rũ', '', ' /ˈfæsɪneɪtɪŋ/', 'a fascinating story/subject The results of the survey made fascinating reading. It''s fascinating to see how different people approach the problem.'),
  ('fashion accessory', NULL, 'null', 'phụ kiện thời trang', '', '', 'null'),
  ('fast food dependency', 'sự phụ thuộc vào thức ăn nhanh', NULL, 'sự phụ thuộc vào thức ăn nhanh', NULL, '/fɑːst fuːd dɪˈpendənsi/', NULL),
  ('fasten', 'verb: to attach or tie tightly to something (not using glue)', 'verb: to attach or tie tightly to something (not using glue)', 'thắt chặt, buộc chặt', '', '', 'The dog''s owner made sure to fasten the leash to a nearby tree with a strong knot to make sure it didn''t escape again.'),
  ('fastidious', 'adjective: giving careful attention to detail', 'adjective: giving careful attention to detail', 'khó tính, kỹ lưỡng', 'meticulous, scrupulous, particular', '/fæˈstɪdiəs/', 'The surgeon''s fastidious attention to each and every tiny cut or stitch frustrated his staff but overjoyed his patients.'),
  ('fatigue', 'noun: extreme tiredness from too much work', 'noun: extreme tiredness from too much work', 'mệt mỏi', NULL, NULL, 'The three-day hula-hooping contest left even the most experienced hula hoopers limp with fatigue.'),
  ('feasible', 'adjective: possible to do without problem', 'adjective: possible to do without problem', 'khả thi', 'possible, viable, practicable', '/ˈfiːzəbəl/', 'Our global economy is so complicated that it is not feasible for one person to understand it entirely.'),
  ('feature', 'noun: an important characteristic, a property; verb: to include as an important piece', 'noun: an important characteristic, a property; verb: to include as an important piece', 'tính năng', NULL, NULL, 'The sound made by "r" is one of the most difficult features of spoken English.
The university''s new student housing features larger rooms than the old building did.'),
  ('fecal', 'thuộc phân', 'relating to excrement', 'thuộc phân', NULL, '/ˈfiːkəl/', NULL),
  ('federation', 'liên bang, liên đoàn', 'a group of states or organizations united under a central body', 'liên bang, liên đoàn', 'union, confederation, alliance', '/fɪd.əˈreɪʃən/', NULL),
  ('feeble', 'adjective: very weak', 'adjective: very weak', 'yếu ớt', NULL, NULL, 'After months of being sick in bed, Harry did not have all of his energy back and felt quite feeble when trying to do even simple things.'),
  ('feel something in your bones', NULL, 'feel very strongly that you are right about something, although you cannot explain why', 'cảm thấy điều gì đó trong xương cốt', '', '', 'Joe, I have a hunch you’re going to lose tonight. I just feel it in my bones.'),
  ('feel the pinch', NULL, 'do not have as much money as used to have, and so cannot buy the things they would like to buy', 'cảm thấy khó khăn', '', '', 'Poor households were still feeling the pinch and new taxes on fuel made matters even worse.'),
  ('fiber', 'sợi, chất xơ', 'a thread or filament forming a natural or synthetic material', 'sợi, chất xơ', 'filament, strand, thread', '/ˈfaɪbər/', NULL),
  ('fibre', NULL, 'any of the thread-like parts that form plant or artificial material and can be made into cloth', 'xơ, sợi, thớ', '', '/ˈfaɪbər/', 'The fibres are woven into fabric nylon and other man-made fibres'),
  ('fiction', NULL, 'a type of literature that describes imaginary people and events, not real ones', 'tác phẩm) hư cấu, tưởng tượng.', '', '/ˈfɪkʃn/', 'a work of popular fiction historical/romantic fiction'),
  ('fictional', 'hư cấu, tưởng tượng', 'invented for a story; not real', 'hư cấu, tưởng tượng', 'invented, imaginary, fabricated', '/fɪkʃənəl/', 'fictional characters a fictional account of life on a desert island fictional techniques the fictional world of Lawrence Durrell The names of the characters are entirely fictional.'),
  ('fifteenth', 'thứ mười lăm', 'constituting number fifteen in a sequence', 'thứ mười lăm', NULL, '/fɪfˈtiːnθ/', NULL),
  ('fight like cat and dog', NULL, 'two people frequently have violent arguments or fights with each other', 'cãi nhau như chó với mèo', '', '', 'My brother and I are very close in age and we used to fight like cat and dog.'),
  ('figurative', 'theo nghĩa bóng, ẩn dụ', 'using figures of speech; metaphorical', 'theo nghĩa bóng, ẩn dụ', 'metaphorical, symbolic, allegorical', '/fiɡʊˈreɪtɪv/', 'For example, ‘He exploded with rage’ shows a figurative use of the verb ‘explode’. Of course, she was using the term "massacre" in the figurative sense.'),
  ('finch', 'chim sẻ, chim finch', 'a small seed-eating songbird', 'chim sẻ, chim finch', NULL, '/fɪntʃ/', NULL),
  ('find', NULL, 'a good or valuable thing or a special person that has been discovered but was not known about before', '(vật tìm thấy)', '', '/faɪnd/', 'This café''s quite a find - I had no idea there was anywhere like it around here. A recent find of ancient artefacts is on display at the local museum.'),
