  ('forge', 'verb: to create (something strong) through a large effort', 'verb: to create (something strong) through a large effort', 'lò rèn(n); chế tạo, tạo ra(v)', '', '', ''),
  ('forgo', 'verb: to decide not to use or have something good', 'verb: to decide not to use or have something good', 'từ bỏ', NULL, NULL, 'Terry had to forgo his summer backpacking trip across Europe in order to save money to fix his car instead.'),
  ('formulation', NULL, 'the activity of creating or preparing something', 'sự tạo thành, sự hình thành', '', '/ˌfɔːrmjuˈleɪʃn/', 'the formulation of new policies new formulations of existing drugs'),
  ('forthcoming', 'adjective: ready or helpful when needed (used with "not" to describe problems)', 'adjective: ready or helpful when needed (used with "not" to describe problems)', 'sắp ra mắt', NULL, NULL, 'Although our education system is suffering badly from a lack of money, help from the government hasn''t been forthcoming.'),
  ('fortuitous', 'tình cờ may mắn', 'happening by chance, often fortunately', 'tình cờ may mắn', 'chance, accidental, serendipitous', '/fɔːrˈtuːɪtəs/', NULL),
  ('fossil', 'hóa thạch', 'the preserved remains of a prehistoric organism', 'hóa thạch', 'remnant, relic, petrifaction', '/ˈfɒsəl/', NULL),
  ('fossil fuel dependency', 'sự phụ thuộc vào nhiên liệu hóa thạch', NULL, 'sự phụ thuộc vào nhiên liệu hóa thạch', NULL, '/ˈfɒsl fjuːəl dɪˈpendənsi/', NULL),
  ('foster', 'verb: to help the growth of something', 'verb: to help the growth of something', 'nuôi dưỡng', NULL, NULL, 'A good teacher not only teaches students how to do well on tests; a good teacher fosters curiosity and excitement to learn in her students.'),
  ('fraction', 'phần số; phần nhỏ', 'a numerical quantity that is part of a whole; a small part', 'phần số; phần nhỏ', 'portion, segment, fragment', '/frækʃən/', NULL),
  ('fracture', 'sự gãy, nứt; làm gãy', 'a break or crack; to break', 'sự gãy, nứt; làm gãy', 'break, crack, rupture', '/frækˈʃʊər/', 'Under the enormous weight of a modern city building, stones without enough support will fracture, leading to collapse.'),
  ('fragment', 'mảnh vỡ; làm vỡ vụn', 'a small broken-off piece; to break apart', 'mảnh vỡ; làm vỡ vụn', 'piece, shard, splinter', '/ˈfræɡmənt/', NULL),
  ('fragrant', 'adjective: having a strong, good smell', 'adjective: having a strong, good smell', 'thơm ngát', NULL, NULL, 'Shirley loved growing roses because they were much more fragrant than the other, more dull smelling flowers in her garden.'),
  ('framework', 'noun: a structure for a building, system, or idea', 'noun: a structure for a building, system, or idea', 'khung, cơ cấu', 'structure, skeleton, scaffold', '/friːm, wɔrk/', 'Ellen''s business plan may have failed, but it formed the framework for her next, successful plan.'),
