  ('fungus', NULL, 'any of various types of organisms that get their food from decaying material or other living things', 'nấm', '', '/ˈfʌŋɡəs/', 'Mushrooms and mould are fungi. Fungus can be poisonous.'),
  ('furthermore', 'adverb: also, in addition', 'adverb: also, in addition', 'hơn nữa', 'moreover, in addition', '/ˌfɜː.ðəˈmɔːr/', 'Kenya has beautiful weather and, furthermore, does not have long nights in the winter.'),
  ('fuse', 'verb: combine into one', 'verb: combine into one', 'hợp nhất(v); cầu chì, ngòi nổ(n)', '', '', 'The two cities of Buda and Pest were separate for centuries, but in the nineteenth century they fused to become Budapest.'),
