  ('galvanize', 'kích thích, thúc đẩy', 'to shock or excite into action', 'kích thích, thúc đẩy', 'stimulate, energize, motivate', '/ˈɡælvənaɪz/', NULL),
  ('garbage collection', NULL, NULL, NULL, NULL, NULL, NULL),
  ('gastronomy', 'nghệ thuật ẩm thực', 'the practice or art of cooking and eating good food', 'nghệ thuật ẩm thực', 'cuisine, culinary art', '/ɡæsˈtrɒnəmi/', NULL),
  ('gaudy', 'adjective: too colorful and overly decorated', 'adjective: too colorful and overly decorated', 'lòe loẹt', NULL, NULL, 'Karen knew the bright pink, skin-tight suit was gaudy, but she had promised her five-year old son that he could pick her clothing for the party.'),
