  ('geometric', 'thuộc hình học', 'relating to geometry or its regular shapes', 'thuộc hình học', 'symmetrical, angular', '/dʒiˈɑːmɨtrɪk/', NULL),
  ('geothermal', 'địa nhiệt', 'relating to internal heat of earth', 'địa nhiệt', 'earth-heat, terrestrial', '/ˌdʒiːoʊˈθɜːrm əl/', NULL),
