  ('get your wires / lines crossed', '', 'mistaken about what someone else means', 'hiểu sai ý nhau, mỗi người 1 ý hiểu', '', '', 'We were supposed to meet at 7 PM, but we must have got our wires crossed because he went to the other restaurant'),
  ('gimmick', NULL, 'an unusual trick or unnecessary device that is intended to attract attention or to persuade people to buy something', 'chiêu trò, mánh lới tiếp thị', '', ' /ˈɡɪmɪk/', 'a promotional/publicity/sales gimmick We don’t use gimmicks to sell our products. The promise of lower taxation may have been just an election gimmick to gain votes.'),
  ('give and take', NULL, 'the way in which two people or groups in a relationship accept that they cannot have everything that they want and that they must sometimes give the other person or group what they want', 'có đi có lại', '', '', 'All good partnerships involve a bit of give and take.'),
  ('give rise to', 'to cause something to happen or exist', 'to cause something to happen or exist', 'làm nảy sinh, gây ra', 'cause, produce, engender', NULL, 'Rapid growth gave rise to serious housing shortages.')
