INSERT INTO vocabulary (word, meaning, english_meaning, vietnamese_meaning, synonyms, phonetic, example) VALUES
  ('give someone a piece of your mind', NULL, '[INFORMAL] speak angrily to them because they have done something to annoy you', 'nói thẳng thắn với ai đó', '', '', 'You can’t let people get away with behaviour like that. You should have given her a piece of your mind!'),
  ('give someone hell', NULL, 'make your life very unpleasant by behaving badly towards you', 'làm cho ai đó khốn đốn', '', '', 'Their younger son gives them hell.'),
  ('give the game away', NULL, 'reveal something which someone had been trying to keep secret', 'bật mí', '', '', 'Eric had intended to make his announcement in an article in The Times but the paper gave the game away by advertising the article a week before publishing.'),
  ('give yourself something to aim for', NULL, 'null', 'tự đặt cho mình một mục tiêu để phấn đấu', '', '', 'null'),
  ('global warming', 'sự nóng lên toàn cầu', NULL, 'sự nóng lên toàn cầu', NULL, '/ˈɡləʊbl ˈwɔːmɪŋ/', NULL),
  ('globally', 'trên toàn cầu', 'relating to the whole world; comprehensively', 'trên toàn cầu', 'worldwide, universally, internationally', '/ˈɡloʊbəli/', NULL),
  ('go all out', NULL, 'try as hard as possible to achieve something', 'dốc hết sức', '', '', 'If I had the choice over again, I would go all out for a degree in the sciences and specialize in teaching.'),
  ('go around in circles', NULL, 'achieve little because they repeatedly deal with the same point or problem', 'đi vòng vòng', '', '', 'My mind was going around in circles, worrying, but I knew that no news was good news.'),
  ('go back to the drawing board', NULL, 'something you have done has not been successful and you have to try another idea', 'quay lại vạch xuất phát', '', '', 'His government should go back to the drawing board to rethink their programme.'),
  ('go belly-up', NULL, '[INFORMAL] fails and does not have enough money to pay its debts', 'phá sản', '', '', 'Factories and farms went belly-up because of the debt crisis.'),
  ('go off on/at a tangent', NULL, 'start saying or thinking something that is not directly connected with what were said or thought before', 'nói lan man', '', '', 'Our teacher would occasionally go off on a tangent and start talking about something totally unrelated to the textbook.'),
