  ('hydrogen', 'khí hyđrô', 'a colorless flammable gas, the lightest element', 'khí hyđrô', NULL, '/haɪdrədʒən/', NULL),
  ('hygiene standards', 'tiêu chuẩn vệ sinh', NULL, 'tiêu chuẩn vệ sinh', NULL, '/ˈhaɪdʒiːn ˈstændədz/', NULL),
  ('hyperbolize', 'phóng đại', 'to exaggerate', 'phóng đại', 'exaggerate, overstate, magnify', '/haɪˈpɜːrbəlaɪ z/', NULL),
  ('hypocritical', NULL, 'pretending to have moral standards or opinions that you do not actually have', 'đạo đức giả, giả nhân giả nghĩa; nói điều mà mình không thực sự tin', '', ' /ˌhɪpəˈkrɪtɪkl/ ', 'It would be hypocritical of me to have a church wedding when I don''t believe in God. Their accusations of corruption are hypocritical - they have been just as corrupt themselves.'),
  ('hypothesis', 'noun: an idea which explains something but is unproven', 'noun: an idea which explains something but is unproven', 'giả thuyết', 'conjecture, supposition, postulate', '/haɪˈpoʊθɛzɪs/', 'to formulate/confirm a hypothesis a hypothesis about the function of dreams There is little evidence to support these hypotheses.'),
  ('hypothesize', 'đưa ra giả thuyết', 'to put forward as a hypothesis; suppose tentatively', 'đưa ra giả thuyết', 'conjecture, postulate, posit', '/haɪˈpoʊθəˌsaɪz/', NULL),
  ('hypothetical', NULL, 'imagined or suggested but not necessarily real or true', 'trên giả thuyết, có thể không có thật', '', '/ˌhaɪpəˈθetɪkl/', 'This is all very hypothetical but supposing Jackie got the job, how would that affect you? I wasn''t asking about anybody in particular—it was a purely hypothetical question.'),
  ('iconoclastic', 'phá bỏ truyền thống', 'attacking established beliefs', 'phá bỏ truyền thống', 'rebellious, heretical, dissenting', '/aɪˌkɑːnəˈklæ stɪk/', NULL),
