  ('idealize', 'lý tưởng hóa', 'to regard as perfect or better than reality', 'lý tưởng hóa', 'glorify, romanticize, exalt', '/aɪˈdiːəlaɪz/', NULL),
  ('idealized', NULL, 'to consider or represent somebody/something as being perfect or better than they really are', 'lý tưởng hóa, không thực tế', '', ' /aɪˈdiːəlaɪz/', 'an idealized view of married life'),
  ('identical', 'giống hệt, đồng nhất', 'exactly the same in every detail', 'giống hệt, đồng nhất', 'indistinguishable, matching, equivalent', '/aɪˈdentɪkl/', NULL),
  ('identification', 'sự nhận dạng, xác định', 'the act of recognizing or establishing identity', 'sự nhận dạng, xác định', 'recognition, detection, determination', '/aɪ.dənˈteɪʃən/', NULL),
  ('identify', 'verb: to name, to show or figure out what something is', 'verb: to name, to show or figure out what something is', 'xác định', NULL, NULL, 'Scientists have not been able to identify the language written on the rocks.'),
  ('identity formation', 'sự hình thành nhân dạng', NULL, 'sự hình thành nhân dạng', NULL, '/aɪˈdentəti fɔːˈmeɪʃn/', NULL),
  ('ideology', 'hệ tư tưởng, ý thức hệ', 'a system of ideas and ideals', 'hệ tư tưởng, ý thức hệ', 'doctrine, philosophy, belief system', '/aɪˈɒlədʒi/', NULL),
  ('idiosyncratic', 'đặc trưng riêng, khác lạ', 'peculiar to an individual', 'đặc trưng riêng, khác lạ', 'distinctive, peculiar, unique', '/ˌɪdiəsɪŋˈkræt ɪk/', NULL),
  ('igneous', 'thuộc đá mácmá, đá lửa', 'relating to rock formed from cooled magma', 'thuộc đá mácmá, đá lửa', NULL, '/ɪɡniəs/', NULL),
  ('ignore', NULL, 'to pay no attention to something', 'Lờ đi, phớt đi, làm ra vẻ không biết đến; kệ, bỏ qua.', '', ' /ɪɡˈnɔːr/', 'He ignored all the ‘No Smoking’ signs and lit up a cigarette. I made a suggestion but they chose to ignore it. We cannot afford to ignore their advice. She deliberately ignored my question and changed the subject.'),
  ('illuminate', 'làm sáng tỏ', 'to make clear or understandable', 'làm sáng tỏ', 'clarify, elucidate, enlighten', '/ɪˈluːmɪneɪt/', NULL),
  ('illusory', 'adjective: not real, based on an illusion', 'adjective: not real, based on an illusion', 'ảo tưởng', NULL, NULL, 'You think you may see water in the distance in a desert, but it is only an illusory effect created by the hot layer of air over the sand.'),
  ('illustrate', 'verb: to explain with an example or picture', 'verb: to explain with an example or picture', 'minh họa', 'demonstrate, exemplify, show', '/ˈɪləstreɪt/', 'Peter illustrated his point by telling a short story.'),
  ('imagination', NULL, 'the ability to create pictures in your mind; the part of your mind that does this', 'Sức tưởng tượng, trí tưởng tượng; sự tưởng tượng.', '', '/ɪˌmædʒɪˈneɪʃn/', 'a vivid/fertile imagination He''s got no imagination. It doesn''t take much imagination to guess what she meant. I won''t tell you his reaction—I''ll leave that to your imagination.'),
  ('imitate', 'bắt chước', 'to copy the behavior of', 'bắt chước', 'mimic, copy, emulate', '/ˈɪmɪteɪt/', NULL),
  ('imitation', 'sự bắt chước', 'the action of using something as a model', 'sự bắt chước', 'copy, mimicry, replication', '/ˌɪmɪˈteɪʃən/', NULL),
  ('immaterial', 'không quan trọng', 'unimportant under the circumstances', 'không quan trọng', 'irrelevant, unimportant, inconsequential', '/ˌɪməˈtɪriəl/', NULL),
  ('immeasurable', NULL, 'too large, great, etc. to be measured', 'vô hạn, mênh mông, không thể đo lường được', '', '/ɪˈmeʒərəbl/', 'to cause immeasurable harm Her contribution was of immeasurable importance.'),
  ('immense', NULL, 'extremely large or great', 'mênh mông, bao la, rộng lớn', '', ' /ɪˈmens/', 'There is still an immense amount of work to be done. The benefits are immense. a project of immense importance To my immense relief, he didn’t notice my mistake.'),
  ('immune resilience', 'khả năng phục hồi của hệ miễn dịch', NULL, 'khả năng phục hồi của hệ miễn dịch', NULL, '/ɪˈmjuːn rɪˈzɪliəns/', NULL),
  ('immutable', 'không thay đổi, bất biến', 'unchanging over time; not subject to change', 'không thay đổi, bất biến', 'unchangeable, fixed, permanent', '/ɪˈmjuːtəbəl/', NULL),
  ('impact', 'noun: an effect that changes a situation; verb: to affect strongly; noun: the force of being hit hard', 'noun: an effect that changes a situation; verb: to affect strongly; noun: the force of being hit hard', 'tác động', NULL, NULL, 'The end of the war had a large impact on economic growth.
My father''s advice hugely impacted my university decision.
The impact of a car crash can send a driver who doesn''t wear a seat belt through the window.'),
  ('impartial', 'adjective: without preference or bias', 'adjective: without preference or bias', 'công bằng, không thiên vị, vô tư', '', '/ɪmˈpɑːrʃl/', 'an impartial inquiry/observer to give impartial advice As chairman, I must remain impartial'),
  ('impartiality', 'sự công bằng, vô tư', 'the quality of being unbiased', 'sự công bằng, vô tư', 'fairness, neutrality, objectivity', '/ɪmˌpɑːrʃiˈælə ti/', NULL),
  ('impede', 'cản trở, ngăn cản', 'to delay or block the progress of', 'cản trở, ngăn cản', 'hinder, obstruct, hamper', '/ɪmˈpɪd/', 'Virginia''s back pains impeded her ability to work, until eventually she had to leave her job entirely.'),
  ('impediment', 'trở ngại', 'a hindrance or obstruction', 'trở ngại', 'obstacle, hindrance, barrier', '/ɪmˈpedɪmənt/', NULL),
  ('impending', 'adjective: happening very soon', 'adjective: happening very soon', 'sắp xảy ra', NULL, NULL, 'The impending doom of our world has been discussed and debated for over 2000 years.'),
  ('imperative', 'cấp thiết, bắt buộc', 'of vital importance; crucial', 'cấp thiết, bắt buộc', 'essential, crucial, vital', '/ɪmˈperətɪv/', NULL),
  ('imperceptible', NULL, 'very small and therefore unable to be seen or felt', 'Không thể cảm thấy; không thể nhận thấy / Rất nhỏ, rất tinh tế', '', '/ˌɪmpərˈseptəbl/', 'imperceptible changes in temperature The differences were imperceptible to all but the most trained eye.'),
  ('imperious', 'kiêu kỳ', 'assuming power without justification', 'kiêu kỳ', 'arrogant, haughty, domineering', '/ɪmˈpɪriəs/', NULL),
  ('impervious', 'không thấm, không bị ảnh hưởng', 'not allowing entry; unable to be affected', 'không thấm, không bị ảnh hưởng', 'impenetrable, resistant, immune', '/ɪmˈpɜːrviəs/', NULL),
  ('impetus', 'noun: a cause or reason to start an action', 'noun: a cause or reason to start an action', 'động lực', NULL, NULL, 'Before John met Amanda, all his shirts were old and filled with holes, but his desire to impress her gave him the impetus to buy all new clothes.'),
  ('implausible', 'adjective: describing a statement that is not believable', 'adjective: describing a statement that is not believable', 'không hợp lý', NULL, NULL, 'Sally knew James was lying because his story was so implausible—nobody could have stayed awake for 80 straight hours.'),
  ('implement', 'thực hiện, thi hành', 'to put a decision or plan into effect', 'thực hiện, thi hành', 'carry out, execute, enact', '/ˈɪmplɪment/', NULL),
  ('implication', 'hàm ý, hệ quả', 'a likely consequence; something suggested indirectly', 'hàm ý, hệ quả', 'consequence, ramification, inference', '/ɪmpləˈkeɪʃən/', NULL),
  ('imply', 'verb: to communicate without saying specifically; to lead to (a conclusion)', 'verb: to communicate without saying specifically; to lead to (a conclusion)', 'ngu ý, hàm ý', 'insinuate, intimate, suggest', '/ɪmˈplaɪ/', 'The president implied that he would not support the new law against selling tobacco, but he didn''t say it clearly.'),
  ('impose', 'verb: to officially order a new rule, tax, or punishment', 'verb: to officially order a new rule, tax, or punishment', 'áp đặt, đặt ra', 'enforce, inflict, levy', '/ɪmˈpoʊz/', 'We''ll soon find out what punishment will be imposed in response to the test results showing the football player used performance-enhancing drugs.'),
  ('improve', NULL, 'to become better than before; to make something/somebody better than before', 'Cải tiến, cải thiện, cải tạo, trau dồi (tư tưởng), mở mang (kiến thức... ).', '', '/ɪmˈpruːv/', 'His quality of life has improved dramatically since the operation. The doctor says she should continue to improve (= after an illness). I hope my French will improve when I go to France.'),
  ('impugn', 'chất vấn, công kích', 'to dispute the truth or validity of', 'chất vấn, công kích', 'challenge, question, attack', '/ɪmˈpjuːn/', NULL),
  ('impulse control', 'kiểm soát xung động', NULL, 'kiểm soát xung động', NULL, '/ˈɪmpʌls kənˈtrəʊl/', NULL),
  ('impulsive tendencies', 'khuynh hướng bốc đồng', NULL, 'khuynh hướng bốc đồng', NULL, '/ɪmˈpʌlsɪv ˈtendənsiz/', NULL),
  ('in addition', 'used to introduce a further point', 'used to introduce a further point', 'ngoài ra, thêm vào đó', 'moreover, furthermore', NULL, 'In addition, the policy created several thousand jobs.'),
  ('in black and white', NULL, 'something have been written proof of it', 'bằng đen trắng', '', '', 'We have a strict, clear rule in black and white, that this sort of behaviour will not be tolerated.'),
  ('in business', NULL, '[SPOKEN] start doing something because you have got everything ready for it', 'trong lĩnh vực kinh doanh', '', '', 'The new software is installed and working, right? Okay, we’re in business.'),
  ('in conclusion', 'used to introduce a final summary', 'used to introduce a final summary', 'tóm lại, kết luận là', 'to sum up, overall', NULL, 'In conclusion, reform is necessary but not sufficient.'),
  ('in contrast', 'used to compare two clearly different things', 'used to compare two clearly different things', 'ngược lại, trái lại', 'conversely, by comparison', NULL, 'Rural areas are emptying. In contrast, cities keep growing.'),
  ('in fact', 'used to add emphasis or correct an impression', 'used to add emphasis or correct an impression', 'trên thực tế', 'indeed, actually', NULL, 'It is not rare; in fact, it affects one in five.'),
  ('in light of', 'considering; because of new information', 'considering; because of new information', 'xét theo, trước tình hình', 'considering, given', NULL, 'In light of these findings, the guidance was revised.'),
  ('in next to no time', NULL, 'in a very short time', 'ngay sắp tới đây', '', '', 'Organizing the party took next to no time. They completed the job in next to no time.'),
  ('in other words', 'used to restate something more clearly', 'used to restate something more clearly', 'nói cách khác', 'that is to say, put differently', NULL, 'Demand outstripped supply; in other words, prices rose.'),
  ('in over your head', NULL, 'in a situation that is too difficult to deal with', 'bị quá sức', '', '', 'He realized that he was in over his head, and that only his family could help him.'),
  ('in particular', 'especially; more than others', 'especially; more than others', 'nói riêng, đặc biệt', 'especially, notably', NULL, 'One finding in particular deserves attention.')
