INSERT INTO vocabulary (word, meaning, english_meaning, vietnamese_meaning, synonyms, phonetic, example) VALUES
  ('in retrospect', NULL, 'thinking about a past event or situation, often with a different opinion of it from the one you had at the time', 'nhìn lại thời gian đã qua, hồi tưởng lại về quá khứ', '', '/ˈretrəspekt/', 'In retrospect, I think that I was wrong. The decision seems extremely odd, in retrospect.'),
  ('in safe hands', NULL, 'being looked after by someone who will make sure they are not harmed or damaged', 'trong tay những người đáng tin cậy', '', '', 'They could get on with their own lives, knowing their girls were in safe hands.'),
  ('in search of greener pastures', 'tìm kiếm một cuộc sống tốt hơn', NULL, 'tìm kiếm một cuộc sống tốt hơn', NULL, '/ɪn sɜːtʃ əv ˈɡriːnə ˈpɑːstʃəz/', NULL),
  ('in someone’s bad books', NULL, '[BRITISH, INFORMAL] done something that has annoyed someone', 'bị ai đó ghét', '', '', 'Thomas knew that having burnt the cakes, he would be in Mrs Simpson’s bad books.'),
  ('in spite of', 'without being affected by; despite', 'without being affected by; despite', 'bất chấp, mặc dù', 'despite, notwithstanding', NULL, 'In spite of the warnings, construction continued.'),
  ('in the blink of an eye', NULL, 'extremely quickly', 'xảy ra trong chớp mắt', '', '', 'There was a huge "boom" and in the blink of an eye the buildings were gone.'),
  ('in the cold light of day', NULL, 'If you think about something in the cold light of day, you think about it clearly and calmly, without the emotions you had at the time it happened, and you often feel sorry or ashamed about it', 'khi đã bình tĩnh suy nghĩ lại (thường là cảm thấy ân hận hoặc xấu hổ', '', '', 'These things always look different in the cold light of day. The next morning, in the cold light of day, Sarah realized what a complete idiot she had been. They had a terrible fight about the mix-up, but in the cold light of day they realized they were both at fault .'),
  ('in the doldrums', NULL, 'not successful and are not making any progress', 'buồn nản, chán nản', '', '', 'The restaurant business, like many other businesses, is in the doldrums.'),
  ('in the loop', NULL, 'Part of a group that is kept up-to-date with information about something', 'nắm rõ tình hình', '', '', 'Not many people knew about the strike but the CEO was almost certainly in the loop.'),
  ('in the pipeline', NULL, 'being planned or developed', 'đang trong quá trình thực hiện', '', '', 'Another development in the pipeline is closed-circuit TV cameras in most stores.'),
  ('in the public eye', NULL, NULL, NULL, NULL, NULL, NULL),
  ('in the red', NULL, 'owe money to someone or to another organization', 'thâm hụt', '', '', 'If you do go into the red, you get charged 30 pence for each transaction while you are overdrawn.'),
  ('in the same boat', NULL, 'in the same unpleasant or difficult situation', 'cùng chung hoàn cảnh', '', '', 'Don’t worry if you are going bald – 40 per cent of men under 35 are in the same boat.'),
  ('in vogue', NULL, NULL, NULL, NULL, NULL, NULL),
  ('inattentive', 'lơ là, không chú ý', 'not paying close attention', 'lơ là, không chú ý', 'absent-minded, distracted, careless', '/ˌɪnəˈtentɪv/', NULL),
  ('incentive', 'noun: a promised reward to motivate', 'noun: a promised reward to motivate', 'khoản khuyến khích', NULL, NULL, 'Tom knew none of his friends would help him move to his new house without an incentive, so he promised to buy everybody pizza at the end of the day.'),
  ('incessant', 'adjective: happening often without stopping (used for bad things)', 'adjective: happening often without stopping (used for bad things)', 'liên tục (for bad things)', '', '', 'Now that they are building a skyscraper next door, the sound of construction is incessant and impossible to escape.'),
  ('inchoate', 'mới chớm, sơ khai', 'just begun and so not fully formed', 'mới chớm, sơ khai', 'incipient, rudimentary, undeveloped', '/ɪnˈkoʊət/', NULL),
  ('incidence', 'tỷ lệ xảy ra, tần suất', 'the rate or frequency of occurrence', 'tỷ lệ xảy ra, tần suất', 'frequency, occurrence, rate', '/ɪnsɪdəns/', NULL),
  ('incipient', 'mới chớm, sơ khai', 'in an initial stage; beginning', 'mới chớm, sơ khai', 'emerging, nascent, developing', '/ɪnˈsɪpiənt/', NULL),
  ('inclination', 'noun: a feeling of wanting to choose one option (often a repeated preference)', 'noun: a feeling of wanting to choose one option (often a repeated preference)', 'độ nghiêng', NULL, NULL, 'Although the inclination is to ride a bike nearer to parked cars, they can be more dangerous than moving ones, as a door may open in front of you.'),
  ('incline', 'noun: an area that is higher at one end and lower at the other', 'noun: an area that is higher at one end and lower at the other', 'độ dốc', NULL, NULL, 'Many houses in San Francisco are built on sharp inclines, so some buildings have three floors on one side but only two on the other.'),
  ('inclusion', 'sự bao gồm, kết nạp', 'the act of including or being included', 'sự bao gồm, kết nạp', 'incorporation, addition', '/ɪnˈkljuːʒən/', NULL),
  ('income inequality', 'bất bình đẳng thu nhập', NULL, 'bất bình đẳng thu nhập', NULL, '/ˈɪnkʌm ˌɪnɪˈkwɒləti/', NULL),
  ('incongruity', 'sự không phù hợp', 'the state of being out of place', 'sự không phù hợp', 'inconsistency, mismatch, discrepancy', '/ˌɪnkɑːŋˈɡruːə ti/', NULL),
  ('incongruous', 'không phù hợp, lạc lõng', 'not in harmony or keeping with the surroundings', 'không phù hợp, lạc lõng', 'inappropriate, mismatched, jarring', '/ɪnˈkɑːŋɡruəs/', NULL),
  ('inconsequential', 'không quan trọng', 'not important or significant', 'không quan trọng', 'insignificant, trivial, negligible', '/ɪnˌkɑːnsɪˈkwenʃəl/', NULL),
  ('inconsiderate', NULL, 'not giving enough thought to other people’s feelings or needs', 'thiếu ý thức, thiếu chu đáo, thiếu quan tâm, thiếu suy xét', '', '/ˌɪnkənˈsɪdərət/', 'inconsiderate behaviour It was inconsiderate of you not to call.'),
  ('inconsistency', NULL, 'a situation in which two things do not match and are opposed', 'sự mâu thuẫn, sự trái nhau; sự không trước sau như một', '', '/ˌɪnkənˈsɪstənsi/', 'There is some inconsistency between the witnesses'' evidence and their earlier statements. I noticed a few minor inconsistencies in her argument.'),
