  ('misinform', NULL, 'to give somebody wrong information about something', 'báo tin tức sai', '', '/ˌmɪsɪnˈfɔːrm/', 'They were deliberately misinformed about their rights. I was told she would be at the meeting, but clearly I was misinformed. The parents had been misinformed about the incident.'),
  ('misinterpret', 'hiểu sai', 'to interpret wrongly', 'hiểu sai', 'misunderstand, misread, misconstrue', '/ˌmɪsɪnˈtɜːrpr ət/', 'His comments were misinterpreted as a criticism of the project. She deliberately misinterpreted the question.'),
  ('misjudge', NULL, 'to form an opinion or idea about someone or something that is unfair or wrong', 'đánh giá sai ai đó hoặc cái gì đó', '', '/ˌmɪsˈdʒʌdʒ/', 'She now realizes that she misjudged him. It is difficult to understand how they could have misjudged the mood of the workforce so badly.'),
  ('mislead', NULL, 'to give somebody the wrong idea or impression and make them believe something that is not true', 'cố tình lừa dối, tạo ấn tượng giả với ai đó', '', '/ˌmɪsˈliːd/', 'He deliberately misled us about the nature of their relationship. Misleading the court in a trial is a serious offence.'),
  ('mismanage', NULL, 'to deal with or manage something badly', 'quản lý kém, xử lý kém', '', '/ˌmɪsˈmænɪdʒ/', 'The department’s budget was badly mismanaged. The restaurant was hopelessly mismanaged by a former rock musician with no business experience.'),
  ('mistrust', NULL, 'to have doubts about the honesty or abilities of someone', 'không tin, nghi ngờ, ngờ vực, hồ nghi', '', '/ˌmɪsˈtrʌst/', 'She mistrusts anyone in a position of authority. I''ve always mistrusted politicians.'),
  ('misunderstand', NULL, 'to fail to understand somebody/something correctly', 'hiểu nhầm', '', '/ˌmɪsʌndərˈstænd/', 'I completely misunderstood her intentions. Don''t misunderstand me—I am grateful for all you''ve done. I thought he was her husband—I must have misunderstood.'),
