INSERT INTO vocab_tags (vocab_id, tag_id)
SELECT v.id, t.id FROM (VALUES
  ('to some extent', 'function:hedge'),
  ('trigger', 'function:cause'),
  ('underlie', 'function:cause'),
  ('underline', 'function:emphasis'),
  ('undermine', 'function:dispute'),
  ('underscore', 'function:emphasis'),
